files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --btn: #0f3460;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  width: 100%;
  max-width: 360px;
}
h1 {
  margin: 0 0 24px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
}
#count {
  display: block;
  font-size: 4rem;
  font-weight: bold;
  margin: 0 0 24px;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}
button {
  flex: 1 1 auto;
  min-width: 80px;
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: bold;
  font-family: inherit;
  color: var(--text);
  background: var(--btn);
  border: 3px solid var(--accent);
  border-radius: 4px;
  cursor: pointer;
  transition: transform 0.1s, background 0.2s;
}
button:hover {
  background: var(--accent);
  color: var(--bg);
}
button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}
button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}
button:focus:not(:focus-visible) {
  outline: none;
}
@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  #count { font-size: 3rem; }
  button { min-width: 60px; padding: 10px 12px; }
}

let count = 0;
const countEl = document.getElementById('count');
const increaseBtn = document.getElementById('increase');
const decreaseBtn = document.getElementById('decrease');
const resetBtn = document.getElementById('reset');

function updateDisplay() {
  countEl.textContent = count;
}

increaseBtn.addEventListener('click', () => {
  count += 1;
  updateDisplay();
});

decreaseBtn.addEventListener('click', () => {
  count -= 1;
  updateDisplay();
});

resetBtn.addEventListener('click', () => {
  count = 0;
  updateDisplay();
});

updateDisplay();
